  $a=Get-ChildItem "$g\$n" -Recurse -File | % { $_.FullName.Substring("$g\$n".Length)+":"+(Get-FileHash $_.FullName).Hash }
  $b=Get-ChildItem "$p\$n" -Recurse -File | % { $_.FullName.Substring((Resolve-Path "$p\$n").Path.Length)+":"+(Get-FileHash $_.FullName).Hash }
  "{0}: differing={1}" -f $n,(Compare-Object $a $b | Measure).Count }

$t="$env:TEMP\agents\tstack"; New-Item -ItemType Directory -Force $t | Out-Null; Set-Location $t
if(-not (Test-Path "$t\tstack")){ git clone --depth 1 https://github.com/t3dotgg/tstack.git 2>&1 | Select -Last 1 }
Get-ChildItem "$t\tstack" -Force | % Name
"--- skills"; Get-ChildItem "$t\tstack" -Recurse -Filter SKILL.md | % { $_.FullName.Replace("$t\tstack\","") }
